tasks.solution:
const tanks = [
  { name: "A", fuel: 42 },
  { name: "B", fuel: 27 },
  { name: "C", fuel: 36 },
];

// calculate total and average
const total = tanks.reduce((sum, t) => sum + t.fuel, 0);
const average = total / tanks.length;

console.log("Total fuel:", total);
console.log("Average:", average);

