project_task.solution:
const players = [
  { name: "Ada", score: 120 },
  { name: "Ben", score: 85 },
  { name: "Emma", score: 150 },
  { name: "Max", score: 95 },
];

function leaderboard(list) {
  // copy, sort, then turn into text with map
  return list
    .slice()
    .sort((a, b) => b.score - a.score)
    .map((p, i) => `${i + 1}. ${p.name} - ${p.score}`);
}

console.log(leaderboard(players));
